template <bool Purposed, class Result>
TenantRequest<Purposed, Result>& TenantRequest<Purposed, Result>::enhanceChildrenIfNeeded() & {
    return *this;
}

template <bool Purposed, class Result>
RecordRequest<Purposed, Result>& RecordRequest<Purposed, Result>::enhanceChildrenIfNeeded() & {
    enhanceChild(NoteRequest<false>(query_.template childQuery<Note>())
                     .unlimited()
                     .selectSelfFields()
                     .enhanceChildrenIfNeeded());
    return *this;
}

template <bool Purposed, class Result>
NoteRequest<Purposed, Result>& NoteRequest<Purposed, Result>::enhanceChildrenIfNeeded() & {
    return *this;
}

class query_factory {
    ContextBinding binding_;

public:
    explicit query_factory(UserContext& user_context) : binding_(user_context) {}

    TenantRequest<false> tenantsMinimal() const {
        return TenantRequest<false>(binding_.get(), true);
    }

    TenantRequest<false> tenants() const {
        return TenantRequest<false>(binding_.get());
    }

    TenantRequest<false> tenantsWithChildren() const {
        return TenantRequest<false>(binding_.get(), true, false)
            .unlimited()
            .selectSelfFields()
            .enhanceChildrenIfNeeded();
    }

    RecordRequest<false> recordsMinimal() const {
        return RecordRequest<false>(binding_.get(), true);
    }

    RecordRequest<false> records() const {
        return RecordRequest<false>(binding_.get());
    }

    RecordRequest<false> recordsWithChildren() const {
        return RecordRequest<false>(binding_.get(), true, false)
            .unlimited()
            .selectSelfFields()
            .enhanceChildrenIfNeeded();
    }

    NoteRequest<false> notesMinimal() const {
        return NoteRequest<false>(binding_.get(), true);
    }

    NoteRequest<false> notes() const {
        return NoteRequest<false>(binding_.get());
    }

    NoteRequest<false> notesWithChildren() const {
        return NoteRequest<false>(binding_.get(), true, false)
            .unlimited()
            .selectSelfFields()
            .enhanceChildrenIfNeeded();
    }
};
